variables._Reserved_SAPFunctionsSAPSystemsQuery:
// let SelectedSystems =  dynamic(["All Systems"]);//can also do:// let SelectedSystems =  dynamic(["S4P", "B4X", "ODT"]);
// let SelectedSystemRoles =  dynamic(["All System Roles"]); //can also do:let SelectedSystemRoles =  dynamic(["Production", "UAT"]);
// let SelectedSystemUsage=  dynamic(["All Usage Types"]); //can also do// let SelectedSystemUsage =  dynamic(["ERP", "CRM"]);
let HearbeatTimeAgo = 1d;
let SystemRolesDictionary= dynamic({"UP":"Unknown (Production)", "AH":"Agent Heartbeat","P":"Production", "T": "Test", "C": "Customizing", "D": "Demo", "E": "Training/Education", "S": "SAP reference"});
let EmptySystems= datatable ( _DTItemId:string, LastUpdatedTimeUTC:datetime, TimeGenerated:datetime, system_id_s: string, SearchKey:string, SystemID:string , SystemRole: string, SystemUsage: string, Priority: int, sap_client_category_s:string, InterfaceAttributes: string )[];
// the 'SAP - Systems' watchlist allows for configuring attributes for each system
let SAPSystemsFromWL= _GetWatchlist('SAP - Systems')
| extend Priority= int(2)
| extend SearchKey= trim_start(@"^[ \t]+",trim_end(@"[ \t]+$",SearchKey))
| extend SystemID= SearchKey
| summarize arg_max(LastUpdatedTimeUTC, *) by SystemID
| extend SystemRole= trim_start(@"^[ \t]+",trim_end(@"[ \t]+$",SystemRole))
| extend SystemUsage= trim_start(@"^[ \t]+",trim_end(@"[ \t]+$",SystemUsage));
// As of agent version 64043801 from November 2022, the hearbeat sends the original system role from SAP
let SAPSystemsFromHeartbeat= CWSQSAP.SAP_HeartBeat_CL
| where TimeGenerated > ago(HearbeatTimeAgo)
| where system_id_s != "AGENT"
| union isfuzzy=true EmptySystems
| summarize arg_max(TimeGenerated, *) by system_id_s
| extend SystemID= substring(system_id_s,0,3)
| summarize arg_max(TimeGenerated, *) by SystemID
| order by SystemID
| extend SystemRoleCode= column_ifexists("sap_client_category_s","UP")
| extend SystemRoleCode= iff(bag_has_key(SystemRolesDictionary,SystemRoleCode), SystemRoleCode, "UP")
| extend SystemRole= tostring(SystemRolesDictionary[SystemRoleCode])
| project SearchKey= SystemID, Priority= int(0), SystemID, SystemRole;
let SAPSystemsFromAuditLog= SAPAuditLog
| where TimeGenerated > ago(HearbeatTimeAgo)
| distinct SystemID, ClientCategory
| extend Priority= int(0)
| union isfuzzy=true EmptySystems
| extend SystemRoleCode= iff(bag_has_key(SystemRolesDictionary,ClientCategory), ClientCategory, "UP")
| extend SystemRole= tostring(SystemRolesDictionary[SystemRoleCode])
| project SearchKey= SystemID, Priority= int(1), SystemID, SystemRole;
union isfuzzy=true EmptySystems, SAPSystemsFromWL, SAPSystemsFromHeartbeat, SAPSystemsFromAuditLog
// allow SystemRole to be controlled by the watchlist so users can set own system role (not the one coming from the hearbeat)
| summarize arg_max(Priority, SystemRole), arg_max(Priority, SystemUsage), arg_max(Priority, *)
by SystemID, SearchKey
| where SearchKey in (SelectedSystems) or tostring(SelectedSystems) contains 'All Systems'
| where SystemRole in (SelectedSystemRoles) or tostring(SelectedSystemRoles) contains 'All System Roles'
| where SystemUsage in (SelectedSystemUsage) or tostring(SelectedSystemUsage) contains 'All Usage Types'
| extend DummyJoinField = 1, SystemUsage=iff(isempty(SystemUsage), "Unknown", SystemUsage)
// set "Production" as default, just in case it cannot be inferred from data. This value is considered for analytics purposes only, and not billing purposes.
| extend SystemRole= iff(isempty(SystemRole), "Production", SystemRole), InterfaceAttributes
| project-away Priority*, LastUpdatedTimeUTC, TimeGenerate*, _DTItemId, *1
| where isnotempty( SystemID)

variables._Reserved_SAPFunctionsSAPUsersEmailQuery:
let UserMDLookBack = totimespan(toscalar(SAPGetParameters('UserMDLookBack')| project-keep ValueLow));
// older agents have to use USR21 to get the ADDRNUMBER, PERSNUMBER before getting the email address from ADR6
let AgentEmailsV1= SAP_USR21 | where TimeGenerated > ago(UserMDLookBack)
| summarize arg_max(TimeGenerated, ADDRNUMBER, PERSNUMBER) by BNAME, MANDT, SystemID
| project-rename CLIENT= MANDT
| join kind= leftouter hint.strategy=shuffle
(SAP_ADR6 | where TimeGenerated > ago(UserMDLookBack)
| summarize arg_max(TimeGenerated, CONSNUMBER ) by CLIENT, DATE_FROM, ADDRNUMBER, PERSNUMBER, SystemID, SMTP_ADDR)
 on ADDRNUMBER, PERSNUMBER, SystemID, CLIENT
| project SystemID, ClientID= CLIENT, User= BNAME, Email= iff(isempty(SMTP_ADDR), BNAME, SMTP_ADDR)
| summarize Email= anyif(Email, isnotempty(Email) ) by ClientID, SystemID, User;
// agents from version 60075287 have the join of USR21 and ADR6 performed
let AgentEmailsV2= SAP_ADR6 | where TimeGenerated > ago(UserMDLookBack)
| summarize arg_max(TimeGenerated, SMTP_ADDR) by BNAME, ClientID= CLIENT, SystemID
| project SystemID, ClientID, User= BNAME, Email= iff(isempty(SMTP_ADDR), BNAME, SMTP_ADDR)
| summarize Email= anyif(Email, isnotempty(Email) ) by ClientID, SystemID, User;
// get the user email coming from an agentless data connector
let AgentLessEmails= CWSQSAP.ABAPUserDetails | where TimeGenerated > ago(UserMDLookBack)
| summarize arg_max(TimeGenerated, Email) by User, ClientID= ClientId, SystemID= SystemId
| extend Email= coalesce(Email, User);
AgentEmailsV1 | union AgentEmailsV2, AgentLessEmails

variables._Reserved_SAPFunctionsSAPUsersHeaderQuer:
// // optional parameters can look like this
// let SelectedSystems =  dynamic(["All Systems"]);
// let SelectedSystemRoles =  dynamic(["All System Roles"]);
// let SelectedUsers = dynamic(["All Users"]);
// let SelectedUser = "All Users";
// let AccountNames= dynamic(["All account names"]);
// // let AccountNames= dynamic(["All account names"]);
// // let SelectedSystems =  dynamic(["S4P", "B4X", "ODT"]);
// // let SelectedSystemRoles =  dynamic(["Production", "UAT"]);
// // let SelectedUsers = dynamic(["DEVELOPER","DDIC"]);
// // let SelectedUser = "DDIC";
let UserMDLookBack = totimespan(toscalar(SAPGetParameters('UserMDLookBack')| project-keep ValueLow));
let UserHeaderAuditLookBack = totimespan(toscalar(SAPGetParameters('UserHeaderAuditLookBack')| project-keep ValueLow));
let Now = now();
let Statuses= dynamic({"0": "Not Locked", "32": "Locked Globally By Administrator", "64": "Locked Locally By Administrator", "128":	"Locked Due To Incorrect Logons (Limited Term)"});
let UserTypes = dynamic({"A": "Dialog", "B": "System", "C": "Communications Data", "L": "Reference (Logon not possible)", "S": "Service"});
let Systems = materialize (SAPSystems(SelectedSystemRoles= SelectedSystemRoles, SelectedSystems=SelectedSystems)
    | project-keep SystemID, SystemRole, SystemUsage);
let AuditEvents= materialize(SAPAuditLog()
| where TimeGenerated > ago(UserHeaderAuditLookBack)
| where SystemID in ((Systems | distinct SystemID))
| where isnotempty( User)
| where Email has_any(AccountNames) or tostring(AccountNames) contains "All account names"
| summarize  TimeGenerated= arg_max(TimeGenerated, ClientID, SystemID, Email) by User, ClientID, SystemID, TerminalIPv6, TERM_IPV6, Email
| lookup kind=inner Systems on SystemID
| project-rename Client= ClientID);
let UserLockUnlockFromAudit= SAPAuditLog
| where TimeGenerated > ago(UserHeaderAuditLookBack)
| where SystemID in ((Systems | distinct SystemID))
// look for changes in agent dataconnector data. Agentless data connector sends this information using CWSQSAP.ABAPUserDetails continuously
| where Type == "ABAPAuditLog_CL"
| where MessageID == "AU9" or MessageID == "AUA"
| where Email has_any(AccountNames) or tostring(AccountNames) contains "All account names"
| extend Action= iff(MessageID == "AUA", "unlocked", "locked")
| summarize ChangedOn= arg_max(UpdatedOn_t, User, Action) by Variable1, SystemID, Client= ClientID
| project-rename User=Variable1, ActingUser=User
| extend Details= strcat("SAP user ", User, " was ", Action, " in system ", SystemID, " - ", Client, " by user ", ActingUser);
let LastKnownIPs = AuditEvents | where isnotempty(TerminalIPv6) or isnotempty( TERM_IPV6)| summarize LastUsedOn= arg_max(TimeGenerated, *) by User, Client, SystemID | project LastKnownIP= coalesce(TerminalIPv6, TERM_IPV6), User, Client, SystemID;
let KnownIPsAndEmails = AuditEvents
| summarize Count= count() by User, Client, SystemID, TerminalIPv6, TERM_IPV6, Email| order by Count desc
| summarize KnownEmails= make_set_if(Email,isnotempty( Email), 10), KnownIPs = make_set_if(TerminalIPv6, isnotempty(TerminalIPv6), 10), KnownIPs2 = make_set_if(TERM_IPV6, isnotempty(TERM_IPV6), 10)
by User, SystemID, Client
| extend KnownIPs= set_union(KnownIPs, KnownIPs2)
| extend PrimaryEmail = KnownEmails[0], PrimaryIP= KnownIPs[0];
let UserDetailsFromAgent= Systems | join kind= inner
// get logon Data (Kernel-Side Use)
(SAP_USR02
| where TimeGenerated > ago(UserMDLookBack)
| where (BNAME in (SelectedUsers) or tostring( SelectedUsers) == '["All Users"]') and (BNAME == SelectedUser or SelectedUser contains "All Users")
| summarize StatusDateTime= arg_max(TimeGenerated, *) by BNAME, MANDT, SystemID )
on SystemID
// get User Name/Address Key Assignment
| join kind=leftouter hint.strategy=shuffle
(SAP_USR21 | where TimeGenerated > ago(UserMDLookBack) | summarize arg_max(TimeGenerated, *) by BNAME, MANDT, SystemID)
on BNAME, MANDT, SystemID
| project-rename CLIENT= MANDT
// get E-Mail Addresses
| join kind= leftouter hint.strategy=shuffle
(SAP_ADR6 | where TimeGenerated > ago(UserMDLookBack)
| summarize LastSynched= arg_max(TimeGenerated, CONSNUMBER ) by CLIENT, DATE_FROM, ADDRNUMBER, PERSNUMBER, SystemID, SMTP_ADDR)
 on ADDRNUMBER, PERSNUMBER, SystemID, CLIENT
| project-rename User= BNAME, Client= CLIENT
| extend LastSeen= todatetime(strcat(TRDAT, LTIME)), CreatedOn = todatetime(ERDAT), ValidFrom= todatetime(GLTGV), Priority= 1
, ValidityDate= todatetime(iff(isempty(GLTGB) or GLTGB == "00000000", "99991231",GLTGB))
| project-rename UserGroup= CLASS, UserType = USTYP, Timezone = TZONE, LockedStatus = UFLAG, Email= SMTP_ADDR;
let UserDetailsFromAgentless= Systems | join kind= inner CWSQSAP.ABAPUserDetails on $left.SystemID == $right.SystemId
| where TimeGenerated > ago(UserMDLookBack)
| where (User in (SelectedUsers) or tostring( SelectedUsers) == '["All Users"]') and (User == SelectedUser or SelectedUser contains "All Users")
| where Email has_any(AccountNames) or tostring(AccountNames) contains "All account names"
| summarize LastSynched=arg_max(TimeGenerated, Email, UserType, Timezone, LockedStatus, LastSeen, CreatedOn, ChangedOn, LastChangedBy, UserGroupAuth= UserGroup, ValidityDate, SystemRole, SystemUsage)
by User, Client= ClientId, SystemID= SystemId
| extend Priority= 1, StatusDateTime= LastSynched, ValidFrom= CreatedOn;
union UserDetailsFromAgentless, UserDetailsFromAgent
// fill user per system for clients that only send audit but not user MD
, (AuditEvents | summarize LastSeenOnAudit=max(TimeGenerated) by User, SystemID, Client | extend Priority= 2)
| order by User, SystemID, Client
| summarize arg_min(Priority, *) by User, SystemID, Client
| lookup KnownIPsAndEmails on User, SystemID, Client
| lookup LastKnownIPs on User, SystemID, Client
| extend LastSeen = max_of(LastSeen, column_ifexists("LastUsedOn", datetime(null)), column_ifexists("LastSeenOnAudit", datetime(null)))
| extend LastSeenDaysAgo = datetime_diff('Day', Now, LastSeen)
| extend CreatedDaysAgo = datetime_diff('Day', Now, CreatedOn)
| project LastSynched=max_of(LastSynched, StatusDateTime, LastSeen, ChangedOn), User, Email = coalesce(Email, PrimaryEmail), LastSeen, LastSeenDaysAgo, PrimaryIP, LastKnownIP,
PrimaryEmail, KnownIPs, KnownEmails, Client, SystemID, SystemRole, SystemUsage, CreatedOn, CreatedDaysAgo, ValidFrom, ValidityDate, LockedStatus, UserType, UserGroup
| lookup UserLockUnlockFromAudit on User, SystemID, Client
| extend LockedStatus= case(LockedStatus contains "Locked", LockedStatus, isempty(Action),trim_start(" ", LockedStatus),Action=="unlocked","0","64")
| extend LockedStatusDescription= coalesce(tostring(Statuses[LockedStatus]), LockedStatus)
| extend UserTypeDescription= tostring(UserTypes[UserType])
| extend LastSynched= max_of(LastSynched, ChangedOn)
| where PrimaryEmail has_any(AccountNames) or tostring(AccountNames) contains "All account names"

