properties.query:
// SAP Java - Sensitive Privileged User Logged in
// here you can exclude certain users which are OK to execute this action
// by adding those users in the SAP_User_Config watchlist with a tag of 'SensitiveLogOnOK'
let excludeUsersTags= dynamic(['SensitiveLogOnOK']);
let excludedUsers= SAPUsersGetVIP(SearchForTags= excludeUsersTags)
    | summarize by User2Exclude=SAPUser;
let PrivilegedUsers = SAPUsersGetPrivileged()
    | project User, SystemID;
let SelectedSystemRoles = dynamic(["Production"]); //can also do// let SelectedSystemRoles =  dynamic(["Production", "UAT"]); dynamic(["All System Roles"])
let SelectedSystems = SAPSystems(SelectedSystemRoles= SelectedSystemRoles)
    | project SystemID= SearchKey, SystemRole;
SAPJAVAFilesLogs()
| where SourceName == "/System/Security/Authentication"
| join kind= inner SelectedSystems on SystemID
| join kind=leftantisemi excludedUsers on $left.User == $right.User2Exclude
| join kind=inner PrivilegedUsers on User, SystemID
| extend Login= tostring(column_ifexists("_Login", ""))
| extend IPAddress= column_ifexists("_IP_Address", "")
| where isnotempty( Login)
| order by TimeGenerated asc
| summarize Count=count(), Time=min(Time), IPAddresses=make_set_if(IPAddress, isnotempty( IPAddress))
, LogonInfo=take_anyif(tostring(Text), isnotempty(Text))
by SystemID, User, SystemRole, Login, Instance
| extend AlertName= strcat("SAP AS JAVA - Privileged User ", User, " Has ", iff(Login == "OK" , "succeeded", "failed")," logging in" )
| extend AlertDescription= strcat("SAP AS JAVA - Privileged User ", User, " Has ", iff(Login == "OK" , "succeeded", "failed")," logging in to a ", SystemRole, " System ", Count, iff(Count > 1, " times. ", "time. "), " \n Login info: ", LogonInfo)
| extend Severity= iff(Login == "OK", "Low", "High")
| extend IPAddress= IPAddresses[0]
| extend AlertRuleUniqueName = 'asjavasensitiveprivilegedusersignedin'
| extend SourceIdentifier= trim("-", strcat_delim("-","SAP", column_ifexists("SystemID", ""), column_ifexists("ClientID", ""), toscalar(SAPGetSourceIdentifier() | project SourceIdentifier)))

//SAP - AS JAVA - High - Login from unexpected network
let SelectedSystemRoles = dynamic(["Production"]); //can also do// let SelectedSystemRoles =  dynamic(["Production", "UAT"]); dynamic(["All System Roles"])
let SelectedSystems = SAPSystems(SelectedSystemRoles= SelectedSystemRoles)
    | project SystemID= SearchKey, SystemRole;
// here you can exclude system users which are OK to execute this action
// by adding those users in the SAP_User_Config watchlist with a tag of "LoginUnExpectedOK"
let excludeUsersTags= dynamic(["LoginUnExpectedOK"]);// dynamic(["LoginUnExpectedOK","SAP_ALL"]);
let excludedUsers= SAPUsersGetVIP(SearchForTags= excludeUsersTags)| summarize by User2Exclude=SAPUser;
let Networks = _GetWatchlist("SAP - Networks");
SAPJAVAFilesLogs()
| where SourceName == "/System/Security/Authentication"
| join kind=leftantisemi excludedUsers on $left.User == $right.User2Exclude
| join kind= inner SelectedSystems on SystemID
| extend Login= tostring(column_ifexists("_Login", ""))
| extend IPAddress= column_ifexists("_IP_Address", "")
| where isnotempty( Login)
| order by TimeGenerated asc
| evaluate ipv4_lookup(Networks, IPAddress, Network, return_unmatched = true)
| where isempty(Network) // Network is not expected
// Details
| summarize Count=count(), Time=min(Time)
, LogonInfo=take_anyif(tostring(Text), isnotempty(Text)), Login=take_any(Login)
by SystemID, User, SystemRole, IPAddress, Instance
| extend GeoLocation= iff(ipv4_is_private( IPAddress), dynamic({"IsPrivate": true}), geo_info_from_ip_address(IPAddress))
| extend AlertName= strcat("SAP AS JAVA - Login from unexpected network ", IPAddress, " by user ", User)
| extend Action= iff(Login contains "OK", " successfully logged in to a "," failed to log in to a ")
| extend AlertDescription= strcat("User ", User, Action, SystemRole, " System ", Count, iff(Count > 1, " times. ", "time. "), " \nLogin info: ", LogonInfo)
| extend Severity= iff(Login == "OK", "Low", "High")
| extend AlertRuleUniqueName = "signinfromunexpectednetwork"
| extend SourceIdentifier= trim("-", strcat_delim("-","SAP", column_ifexists("SystemID", ""), column_ifexists("ClientID", ""), toscalar(SAPGetSourceIdentifier() | project SourceIdentifier)))

