let LogonMethods = datatable(Key: string , Value: string )
["P","Password","T","Logon ticket","t","Assertion ticket","X","X.509 certificate","S","SNC","R","RFC ticket","A","Authorized impersonation (background processing)","E","External (EXTID)","U","User switch","s","HTTP security session","2","SAML2","1","SAML1","o","OAuth2","N","SPNego","a","APC session"]
