// | extend AllPacked= pack_all()
// | summarize AllPacked= make_set(AllPacked)
// | project ZippedPacked= zlib_compress_to_base64_string(tostring(AllPacked));
// PackedConfig
let ZippedInitialConfig= "";
let ExtractedInitialConfig= todynamic(zlib_decompress_from_base64_string(ZippedInitialConfig));
// priority 2 is coming from this function to be used as fall back in case we want to add an item without risking overwriting an existing one
let UnpackedConfig= print InitialConfigArr= ExtractedInitialConfig
| mv-expand bagexpansion= array InitialConfigArr
| evaluate bag_unpack(InitialConfigArr)
| extend _DTItemId = tostring(_DTItemId)
| extend LastUpdatedTimeUTC= todatetime('20000101')
| extend AnalyticsTemplateId = tostring(AnalyticsTemplateId)
| extend Source= "Function";
//  priority 1 is what is there on the watchlist. so when u edit a watchlist and it'll always overwrite
let ARMetaData= ARMetaDataConfig
| extend AnalyticsTemplateId = tostring(AnalyticsTemplateId)
| extend Source= "Watchlist"
| summarize arg_max(LastUpdatedTimeUTC, *) by SearchKey
| project-away SearchKey;
let Teams= materialize(_GetWatchlist("SAPSolutionConfig") | where SearchKey  == "Teams" | project Team= ConfigKey, TeamsChannel, TeamsGroup, Email);
ARMetaData
| union UnpackedConfig
| summarize arg_max(LastUpdatedTimeUTC, *) by RuleID
| lookup Teams on $left.Tier1 == $right.Team
| project-rename Tier1TeamsChannel= TeamsChannel, Tier1TeamsGroup= TeamsGroup, Tier1Email= Email
| lookup Teams on $left.Tier2 == $right.Team
| project-rename Tier2TeamsChannel= TeamsChannel, Tier2TeamsGroup= TeamsGroup, Tier2Email= Email
| project-rename ItemId= _DTItemId
| extend AnalyticsTemplateId= coalesce(tostring(AnalyticsTemplateId), "DefaultRule")
| extend PackedDetails= pack_all()

